/* Texture work is dirty-region-only; moving the slab changes its quad, not pixels. */
static void sync_terrain_texture(void){if(!wallTexture||!wallFacePixels||!terrain.active)return;if(wallTextureSerial==terrain.serial&&wallTextureRevision==terrain.revision)return;
 int fresh=wallTextureSerial!=terrain.serial,l=fresh?0:clamp(terrain.dirtyLeft-2,0,TERRAIN_W-1),r=fresh?TERRAIN_W-1:clamp(terrain.dirtyRight+2,0,TERRAIN_W-1),t=fresh?0:clamp(terrain.dirtyTop-2,0,TERRAIN_H-1),b=fresh?TERRAIN_H-1:clamp(terrain.dirtyBottom+2,0,TERRAIN_H-1);
 if(l<=r&&t<=b){for(int ty=t*2;ty<=(b+1)*2-1;ty++)for(int tx=l*2;tx<=(r+1)*2-1;tx++){int x=tx/2,y=ty/2,i=y*TERRAIN_W+x,m=terrain_material(x,y),u=(m%2)*(wallFaceW/2)+tx*(wallFaceW/2-1)/(TERRAIN_W*2-1),v=(m/2)*(wallFaceH/2)+ty*(wallFaceH/2-1)/(TERRAIN_H*2-1);unsigned char*src=wallFacePixels+(v*wallFaceW+u)*4,*dst=wallRGBA+(ty*TERRAIN_W*2+tx)*4;int solid=terrain.density[i]>0,edge=solid&&((x>0&&!terrain.density[i-1])||(x<TERRAIN_W-1&&!terrain.density[i+1])||(y>0&&!terrain.density[i-TERRAIN_W])||(y<TERRAIN_H-1&&!terrain.density[i+TERRAIN_W]));float shade=edge?.57f:solid?.8f+.2f*terrain.density[i]/terrain_hardness(m):1;for(int c=0;c<3;c++)dst[c]=(unsigned char)(src[c]*shade);dst[3]=solid?255:0;}
 SDL_Rect rect={l*2,t*2,(r-l+1)*2,(b-t+1)*2};SDL_UpdateTexture(wallTexture,&rect,wallRGBA+(t*2*TERRAIN_W*2+l*2)*4,TERRAIN_W*8);wallUploads++;}
 wallTextureSerial=terrain.serial;wallTextureRevision=terrain.revision;terrain.dirtyLeft=TERRAIN_W;terrain.dirtyTop=TERRAIN_H;terrain.dirtyRight=terrain.dirtyBottom=-1;
}
static void draw_fine_terrain(void){if(!terrain.active)return;sync_terrain_texture();float fraction=fmaxf(0,fminf(1,visualTick-g.tick+1)),y=-462+(terrain.previousScrollQ+(terrain.scrollQ-terrain.previousScrollQ)*fraction)/Q;nquad=0;quad(-24,y*3,TERRAIN_W*3,TERRAIN_H*3,(SDL_FColor){1,1,1,1},0,0,1,1);flush(wallTexture);
 static const int colours[4][3]={{155,140,123},{150,225,255},{210,184,140},{205,120,255}};SDL_SetRenderDrawBlendMode(renderer,SDL_BLENDMODE_BLEND);for(int n=0;n<TERRAIN_DEBRIS;n++){TerrainChip*c=terrain.chips+n;if(!c->life)continue;const int*rgb=colours[c->material];SDL_SetRenderDrawColor(renderer,rgb[0],rgb[1],rgb[2],(Uint8)clamp(c->life*14,0,240));SDL_FRect box=camera_rect((SDL_FRect){c->x/(float)Q*3,c->y/(float)Q*3,n&1?3:4.5f,2.5f});SDL_RenderFillRect(renderer,&box);}
}
